#!/usr/bin/env node
/**
 * Ensure data/snapshot.json exists — an empty stub so tsc and next can import
 * it. The real snapshot is generated by CI (scripts/snapshot.mjs) before every
 * deploy; nothing in git depends on its contents. Without this, a fresh clone
 * fails type-check. Never writes a snapshot that claims to be real.
 */
import { writeFileSync, mkdirSync, existsSync, readFileSync } from 'node:fs';

if (existsSync('data/snapshot.json')) process.exit(0);

const record = (() => {
  try {
    const r = JSON.parse(readFileSync('contracts/deployments/testnet.json', 'utf8'));
    return { network: r.network, contractId: r.contracts?.team?.contractId ?? null };
  } catch {
    return { network: 'testnet', contractId: null };
  }
})();

const stub = {
  generatedAt: null,
  network: record.network ?? 'testnet',
  contractId: record.contractId,
  counts: { categories: 0, forums: 0, threads: 0, posts: 0, reactions: 0 },
  categories: [],
  forums: [],
  threads: [],
  profiles: {},
};
mkdirSync('data', { recursive: true });
writeFileSync('data/snapshot.json', JSON.stringify(stub, null, 2) + '\n');
console.log('snapshot stub written (empty — CI generates the real one)');
